use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

use gpui::{Context, IntoElement, Render, TestAppContext, VisualTestContext, Window, WindowHandle};
use gpui_rhai::*;
use gpui_rhai_registry::{
    BUNDLED_ASSET_SOURCES, BUNDLED_COMPONENT_SOURCES_BY_ID, BUNDLED_LAYOUT_SOURCES_BY_ID,
    BUNDLED_PATTERN_SOURCES_BY_ID, DEFAULT_THEME,
};

struct Host {
    host: ScriptViewHost,
    view: Option<ScriptViewHandle>,
}

impl Render for Host {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        match &self.view {
            Some(view) => self.host.container(view.element().unwrap()).into_any_element(),
            None => gpui::div().into_any_element(),
        }
    }
}

const SCRIPT: &str = r#"
fn line(label) {
    text(label).with_style(style().min_height(theme_length("metrics.row")).items_center())
}
fn content() {
    column([line("Line 1"), line("Line 2")])
        .accessibility_role("group").accessibility_label("content")
}
fn scene(density, height) {
    let part = collapsible::Collapsible(#{ key: "details", open: true,
        trigger: text("Details"), content: content(), content_height: height });
    column([part, text("after")]).env(#{ density: density })
        .with_style(style().width(px(300)))
}
"#;

fn mount(
    cx: &mut TestAppContext,
    view_body: &str,
) -> Result<(VisualTestContext, ScriptViewHandle), String> {
    let mut modules = BTreeMap::new();
    let tables = [
        BUNDLED_COMPONENT_SOURCES_BY_ID,
        BUNDLED_LAYOUT_SOURCES_BY_ID,
        BUNDLED_PATTERN_SOURCES_BY_ID,
    ];
    for (id, source) in tables.iter().flat_map(|t| t.iter()) {
        modules.insert(ModuleId::parse(*id).unwrap(), (*source).to_owned());
    }
    let main = format!(
        r#"
import "components/collapsible" as collapsible;
{SCRIPT}
fn view(ctx) {{ column([{view_body}]).with_style(style().width(px(400)).height(px(400))) }}
"#
    );
    let entry = ModuleId::parse("main").unwrap();
    modules.insert(entry.clone(), main);
    let prepared =
        EmbeddedScriptView::new(entry, EmbeddedScriptSource::new(modules), DEFAULT_THEME)
            .token_base(gpui_rhai_registry::TOKEN_BASE_SOURCE)
            .motion_preference(MotionPreference::None)
            .asset_sources(BUNDLED_ASSET_SOURCES.iter().map(|(path, source)| {
                (
                    path.strip_suffix(".svg").unwrap_or(path).to_owned(),
                    AssetData {
                        mime_type: "image/svg+xml".to_owned(),
                        bytes: source.as_bytes().to_vec(),
                    },
                )
            }))
            .prepare()
            .map_err(|error| format!("{error:?}"))?;
    let captured = Rc::new(RefCell::new(None));
    let capture = captured.clone();
    let window: WindowHandle<Host> = cx.add_window(move |window, cx| {
        let host = ScriptViewHost::new("collapsible", cx).unwrap();
        let view = prepared
            .mount(ScriptViewConfig::new("collapsible"), host.clone(), window, cx)
            .map_err(|error| format!("{error:?}"));
        *capture.borrow_mut() = Some(view.clone());
        Host { host, view: view.ok() }
    });
    cx.run_until_parked();
    let view = captured.borrow().clone().unwrap()?;
    let mut visual = VisualTestContext::from_window(*window, cx);
    visual.run_until_parked();
    visual.update(|window, _| window.refresh());
    visual.run_until_parked();
    Ok((visual, view))
}

/// Blank space between the content's bottom and the next sibling, in pixels.
fn blank_below(cx: &mut TestAppContext, density: &str, height: i64) -> f64 {
    cx.update(gpui_rhai::install);
    let (mut visual, view) = mount(cx, &format!(r#"scene("{density}", {height})"#)).unwrap();
    let (content, after) = visual.update(|_, cx| {
        let snapshot = view.accessibility_snapshot(cx).unwrap();
        let bounds = |role: &str, name: &str| {
            let g = snapshot
                .find_by_role_and_name(role, name)
                .next()
                .unwrap_or_else(|| panic!("no {role} {name:?}"))
                .geometry
                .clone()
                .unwrap()
                .layout;
            (g.x, g.y, g.width, g.height)
        };
        (bounds("group", "content"), bounds("text", "after"))
    });
    let blank = after.1 - (content.1 + content.3);
    eprintln!(
        "{density}, content_height {height}: content (x, y, w, h) = {content:?}, next sibling y = {}, blank = {blank}",
        after.1
    );
    blank
}

// Two metrics.row lines (2 x 32) plus padding_bottom(metrics.inset) (12), comfortable.
const COMFORTABLE_FIT: i64 = 76;

#[gpui::test]
fn content_height_fits_in_comfortable(cx: &mut TestAppContext) {
    let blank = blank_below(cx, "comfortable", COMFORTABLE_FIT);
    assert!(blank.abs() < 0.5, "control: {blank}px blank in comfortable");
}

#[gpui::test]
fn the_same_panel_fits_in_compact(cx: &mut TestAppContext) {
    let blank = blank_below(cx, "compact", COMFORTABLE_FIT);
    assert!(
        blank.abs() < 0.5,
        "compact: the content shrinks with density but content_height does not: {blank}px blank"
    );
}

#[gpui::test]
fn integer_content_height_mounts(cx: &mut TestAppContext) {
    cx.update(gpui_rhai::install);
    let result = mount(cx, r#"scene("compact", 76)"#);
    assert!(result.is_ok(), "control: {:?}", result.err());
}

#[gpui::test]
fn density_aware_content_height_mounts(cx: &mut TestAppContext) {
    cx.update(gpui_rhai::install);
    let result = mount(
        cx,
        // A density-aware Length (Length + Length is not defined, so only the rows).
        r#"scene("compact", theme_length("metrics.row") * 2)"#,
    );
    if let Err(error) = &result {
        eprintln!("Length content_height: {error}");
    }
    assert!(
        result.is_ok(),
        "content_height only takes integer pixels, so it cannot follow density"
    );
}
