    findings
}

fn spacing(findings: &[(String, String, String)]) -> Vec<String> {
    findings
        .iter()
        .filter(|(rule, _, _)| rule == "spacing-not-nested")
        .map(|(rule, path, message)| format!("{rule} at {path}: {message}"))
        .collect()
}

