#[gpui::test]
fn a_pushed_sticky_group_header_stays_below_the_column_header(cx: &mut TestAppContext) {
    let (mut visual, view) = mount(cx, false);
    let before = nodes(&mut visual, &view);
    let header_bottom = before
        .iter()
        .filter(|(role, _, _)| role == "columnheader")
        .map(|(_, _, b)| b.y + b.height)
        .fold(f64::MIN, f64::max);
    let first_group = before
        .iter()
        .find(|(role, name, _)| role == "rowheader" && name.starts_with("A"))
        .map(|(_, _, b)| *b)
        .expect("group A header");
    let row = first_group.height;
    // Scroll until group B's header sits 10px below the body top: the sticky A header is
    // then pushed up by row - 10. Wheel steps are applied in pieces, so step until there.
    let body_top = first_group.y;
    for _ in 0..20 {
        let now = nodes(&mut visual, &view);
        let b_top = now
            .iter()
            .find(|(role, name, _)| role == "rowheader" && name.starts_with("B"))
            .map_or(body_top + 1000.0, |(_, _, b)| b.y);
        let remaining = b_top - (body_top + 10.0);
        if remaining.abs() < 0.5 {
            break;
        }
        #[allow(clippy::cast_possible_truncation)]
        let step = remaining.min(row * 4.0) as f32;
        visual.simulate_event(gpui::ScrollWheelEvent {
            position: point(px((first_group.x + 20.0) as f32), px((body_top + 60.0) as f32)),
            delta: gpui::ScrollDelta::Pixels(point(px(0.0), px(-step))),
            ..gpui::ScrollWheelEvent::default()
        });
        visual.run_until_parked();
        visual.update(|window, _| window.refresh());
        visual.run_until_parked();
    }
    let after = nodes(&mut visual, &view);
    let headers: Vec<_> = after
        .iter()
        .filter(|(role, _, _)| role == "rowheader")
        .map(|(_, name, b)| (name.clone(), b.y, b.height))
        .collect();
    assert!(headers.iter().any(|(name, _, _)| name.starts_with("B")), "scrolled to group B: {headers:?}");
    for (name, top, _) in &headers {
        assert!(
            *top + 0.5 >= header_bottom,
            "group header {name} paints at y={top}, above the column header bottom {header_bottom}: {headers:?}"
        );
    }
}
