    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        self.host.container(self.view.element().unwrap())
    }
}

fn audit(cx: &mut TestAppContext, view_body: &str) -> Vec<String> {
    cx.update(gpui_rhai::install);
    let entry = ModuleId::parse("main").unwrap();
    let main = format!("fn view(ctx) {{ column([{view_body}]) }}");
    let prepared = EmbeddedScriptView::new(
        entry.clone(),
        EmbeddedScriptSource::new(BTreeMap::from([(entry, main)])),
        DEFAULT_DARK,
    )
    .token_base(gpui_rhai_registry::TOKEN_BASE_SOURCE)
    .profile_source(PROFILE)
    .motion_preference(MotionPreference::None)
    .prepare()
    .unwrap();
    let captured = Rc::new(RefCell::new(None));
    let capture = captured.clone();
    let window: WindowHandle<Host> = cx.add_window(move |window, cx| {
        let host = ScriptViewHost::new("audit", cx).unwrap();
        let view = prepared
            .mount(ScriptViewConfig::new("audit"), host.clone(), window, cx)
            .unwrap();
        *capture.borrow_mut() = Some(view.clone());
        Host { host, view }
    });
    cx.run_until_parked();
    let view = captured.borrow().clone().unwrap();
    let mut visual = VisualTestContext::from_window(*window, cx);
    visual.run_until_parked();
    visual
        .update(|_, cx| view.composition_audit(cx).unwrap())
        .into_iter()
        .map(|finding| format!("{} at {}", finding.rule.id(), finding.path))
        .collect()
}

