// when the virtual body realizes new rows next to retained ones (0.1.8).
// Place at tests/native-keyboard/tests/adornment_virtual_rows.rs and run:
//   cargo test --manifest-path tests/native-keyboard/Cargo.toml --test adornment_virtual_rows -- --nocapture
use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

use gpui::{
    Context, IntoElement, Modifiers, Render, ScrollDelta, ScrollWheelEvent, TestAppContext,
    VisualTestContext, Window, point, px,
};
use gpui_rhai::*;

const MAIN: &str = r#"
import "components/table" as table;
fn view(ctx) {
    let rows = [];
    for i in 0..60 {
        rows.push(#{ id: `r${i}`, name: `cluster-${i}`, state: "running", variant: "success" });
    }
    table::Table(#{ key: "tce-table", label: "Clusters", row_key: "id", rows: rows,
        columns: [
            #{ key: "name", title: "Cluster", width: #{ kind: "flex", value: 1.0 },
                adornments: [#{ text_key: "state", variant_key: "variant", dot: true }] },
        ],
        height: 200 })
}
"#;

struct Host {
    host: ScriptViewHost,
    view: ScriptViewHandle,
}

impl Render for Host {
    fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
        self.host.container(self.view.element().unwrap())
    }
}

fn realized_rows(visual: &mut VisualTestContext, view: &ScriptViewHandle) -> (usize, usize) {
    let indexes: Vec<usize> = visual.update(|_, cx| {
        view.accessibility_snapshot(cx)
            .unwrap()
            .nodes()
            .filter_map(|node| {
                let at = node.name.find("cluster-")?;
                node.name[at + 8..]
                    .split(|c: char| !c.is_ascii_digit())
                    .next()?
                    .parse()
                    .ok()
            })
            .collect()
    });
    (
        indexes.iter().copied().min().unwrap_or(0),
        indexes.iter().copied().max().unwrap_or(0),
    )
}

#[gpui::test]
fn scrolling_an_adorned_table_realizes_new_rows_without_duplicate_paths(cx: &mut TestAppContext) {
    cx.update(gpui_rhai::install);
    let registry = concat!(env!("CARGO_MANIFEST_DIR"), "/../../registry");
    let read = |path: &str| std::fs::read_to_string(format!("{registry}/{path}")).unwrap();
    let entry = ModuleId::parse("main").unwrap();
